"""Compiled checks for C3-S3. GENERATED by solution/recompute.py. DO NOT HAND-EDIT.

The graded object is a MIXTURE: a corpus drawn from four labelled source corpora to a hard token
cap, and the manifest that says in what proportion. The trainer, the evaluator and the tokenizer
are frozen and hash-pinned, so nothing below inspects a model. Every check reads delivered bytes --
the submitted manifest and span table, the shipped source manifest, or the harness's own record of
what the verifier measured and what the frozen trainer consumed -- and references no unmeasured
quantity, except worst_domain_bits_per_byte_ramp, which calls require_measured before it reads anything at all.
"""
import json
import os

HERE = os.path.dirname(os.path.abspath(__file__))
BUNDLE = os.path.dirname(HERE)
SUBMISSION = '/submission/c3s3.json'
CHECKS = []

# THE FOUR DOMAINS, in the fixed order the four per-domain values are reduced by max. The order is
# part of the grading contract and not a presentation choice: b_worst is an argmax over four
# floats, and a tie broken by dictionary order is a tie broken differently on a different build.
DOMAINS = ('web', 'encyclopedic', 'scientific', 'mathematical')

# The corpus layout, from solution/grounding.yaml's corpus_layout block. NOT LANDED in this
# bundle: these are the paths the landing wave writes to. Every reader below reports an absent
# path rather than guessing at what it would have contained.
SOURCE_MANIFEST = os.path.join(BUNDLE, 'environment/data/sources.json')
FROZEN_TOKENIZER = 'environment/frozen/tokenizer.json'
FROZEN_TRAINER = 'environment/frozen/trainer.py'
FINGERPRINTS = 'environment/decontam/heldout_fingerprints.bin'
HELDOUT_SHARDS = ('tests/heldout/web.bin', 'tests/heldout/encyclopedic.bin', 'tests/heldout/scientific.bin', 'tests/heldout/mathematical.bin')
RUN_RECORD = os.path.join(BUNDLE, 'run_record.json')

# DISCLOSED TASK PARAMETERS, not measurements. Every one is published in instruction.md and none
# is a ramp constant: the cap is announced as a hard literal, and the four bits-per-byte values it
# is spent to lower never are.
TOKEN_BUDGET = 1000000000
WEIGHT_TOLERANCE = 0.005
BUILD_WALL_SECONDS = 1200
TRAIN_WALL_SECONDS = 900
NGRAM_WIDTH = 13
INTERLEAVE_BLOCKS = 8

# The two real reference carriers the environment ships, plus the published tables the archetype
# expects to be recalled. Citing one is fine. Citing nothing else is the failure.
DECOY_TOKENS = ('quality_score', 'quality_classifier', 'dataset_card', 'model_card', 'published_mixture', 'the_pile', 'redpajama', 'dolma')

# The closed reason set from seed/contract.yaml. A failing check names one of these or names a
# diagnostic of its own; the agent-visible surface still receives one float and at most one code.
ZERO_REASONS = ('no-submission', 'eval-leak', 'foreign-content', 'declared-mixture-divergence', 'recipe-corpus-divergence', 'token-budget-exceeded', 'build-wallclock-exceeded', 'train-wallclock-exceeded', 'heldout-touched', 'grading-tree-write', 'frozen-trainer-modified', 'submission-size-exceeded', 'nondeterministic-submission')


class ConstantUnmeasured(Exception):
    """Raised when a check needs a ramp constant that Phase 0 deliberately left null."""


def check(id, weight, knockout, kind):
    def deco(fn):
        CHECKS.append({"id": id, "weight": weight, "knockout": knockout, "kind": kind, "fn": fn})
        return fn
    return deco


def constants():
    with open(os.path.join(HERE, "constants.json")) as fh:
        return json.load(fh)


def require_measured(*names):
    c = constants()
    missing = [n for n in names if c.get(n) is None]
    if missing:
        raise ConstantUnmeasured(
            "C3-S3: " + ", ".join(missing) + " are null. Phase 0 authors no measurement; "
            "the Phase 2 measurement wave writes these and this check becomes gradeable then.")
    return c


def evidence(**kw):
    return {"evaluation_target": kw.pop("target", "emitted_corpus"), "values": kw}


@check(id="cross_domain_duplicates_charged_to_one_domain", weight=4, knockout=False, kind="dedup")
def test_cross_domain_duplicates_charged_to_one_domain():
    try:
        policy = mixture_manifest().get("dedup")
    except Exception as exc:
        return False, evidence(target="mixture_manifest", error=str(exc),
                               reason="dedup-policy-undeclared")
    if not isinstance(policy, dict):
        return False, evidence(target="mixture_manifest", reason="dedup-policy-undeclared",
                               detail="mixture_manifest.dedup names no granularity for either scope")
    within = str(policy.get("within_domain_granularity", "")).strip().lower()
    across = str(policy.get("across_domain_granularity", "")).strip().lower()
    groups = measured().get("cross_domain_duplicate_groups")
    if not isinstance(groups, int) or isinstance(groups, bool):
        return False, evidence(target="mixture_manifest",
                               reason="cross-domain-duplicate-scan-unavailable",
                               within_domain_granularity=within,
                               across_domain_granularity=across)
    ok = bool(within) and across.startswith("document") and groups == 0
    return ok, evidence(target="mixture_manifest", within_domain_granularity=within,
                        across_domain_granularity=across, cross_domain_duplicate_groups=groups,
                        reason=None if ok else "cross-domain-duplicates-double-counted")


@check(id="every_domain_receives_a_nonzero_token_share", weight=4, knockout=False, kind="domain_coverage")
def test_every_domain_receives_a_nonzero_token_share():
    realised = integer_domain_map("per_domain_tokens")
    if not realised:
        # An unmeasured count and a zero count are different claims, and only one of them is
        # about the agent. Neither is allowed to pass.
        return False, evidence(reason="realised-counts-unavailable",
                               detail="the verifier recorded no four-domain integer token counts")
    empty = [domain for domain in DOMAINS if realised[domain] <= 0]
    return (not empty), evidence(per_domain_tokens=realised, empty_domains=empty,
                                 reason=None if not empty else "domain-share-zero")


@check(id="four_domains_interleaved_across_the_single_pass", weight=4, knockout=False, kind="curriculum")
def test_four_domains_interleaved_across_the_single_pass():
    order = emitted_domain_order()
    if not order:
        return False, evidence(reason="emission-domains-unresolved",
                               detail="the emitted order carries no span domains to block up")
    block = measured()
    passes = block.get("consumption_passes")
    single_pass = (bool(block.get("consumption_order_matches_emission"))
                   and isinstance(passes, int) and not isinstance(passes, bool) and passes == 1)
    if len(order) < INTERLEAVE_BLOCKS * len(DOMAINS):
        return False, evidence(records=len(order), blocks=INTERLEAVE_BLOCKS,
                               reason="corpus-shorter-than-the-interleave-window",
                               detail="fewer records than one per domain per block, so an "
                                      "interleaved curriculum could not be expressed")
    size = (len(order) + INTERLEAVE_BLOCKS - 1) // INTERLEAVE_BLOCKS
    starved = {}
    for index in range(INTERLEAVE_BLOCKS):
        seen = set(order[index * size:(index + 1) * size])
        absent = [domain for domain in DOMAINS if domain not in seen]
        if absent:
            starved[index] = absent
    ok = single_pass and not starved
    return ok, evidence(records=len(order), blocks=INTERLEAVE_BLOCKS, block_size=size,
                        consumption_order_matches_emission=block.get(
                            "consumption_order_matches_emission"),
                        consumption_passes=passes,
                        blocks_missing_a_domain=dict((str(k), v) for k, v in starved.items()),
                        reason=None if ok else "emission-curriculum-not-interleaved")


@check(id="frozen_tokenizer_trainer_and_four_heldout_shards_unmoved", weight=5, knockout=True, kind="integrity")
def test_frozen_tokenizer_trainer_and_four_heldout_shards_unmoved():
    block = measured()
    before = block.get("frozen_digests_before")
    after = block.get("frozen_digests_after")
    before = before if isinstance(before, dict) else {}
    after = after if isinstance(after, dict) else {}
    required = (FROZEN_TRAINER, FROZEN_TOKENIZER, FINGERPRINTS) + tuple(HELDOUT_SHARDS)
    uncovered = [path for path in required if path not in before or path not in after]
    moved = sorted(path for path in before if after.get(path) != before[path])
    touched = sorted(str(path) for path in (run_record().get("guarded_paths_touched") or []))
    ok = not uncovered and not moved and not touched and set(before) == set(after)
    if touched:
        reason = "heldout-touched"
    elif moved:
        reason = "frozen-trainer-modified"
    elif uncovered or set(before) != set(after):
        reason = "frozen-digest-record-incomplete"
    else:
        reason = None
    return ok, evidence(target="frozen_grading_tree", paths_required=list(required),
                        paths_uncovered=uncovered, digests_moved=moved,
                        guarded_paths_touched=touched, reason=reason)


@check(id="heldout_thirteen_grams_absent_in_every_domain", weight=5, knockout=True, kind="leakage")
def test_heldout_thirteen_grams_absent_in_every_domain():
    block = measured()
    hits = block.get("fingerprint_hits")
    if not isinstance(hits, dict):
        return False, evidence(reason="eval-leak",
                               detail="no four-domain fingerprint scan is recorded; an unscanned "
                                      "corpus is not a clean one")
    counts, unscanned = {}, []
    for domain in DOMAINS:
        value = hits.get(domain)
        if not isinstance(value, int) or isinstance(value, bool):
            unscanned.append(domain)
        else:
            counts[domain] = value
    width = block.get("ngram_width")
    scope = block.get("fingerprint_scan_scope")
    attributed = block.get("fingerprint_scan_by")
    leaking = sorted(domain for domain, value in counts.items() if value != 0)
    ok = (not unscanned and not leaking and width == NGRAM_WIDTH
          and scope == "full_emitted_corpus" and attributed == "verifier")
    return ok, evidence(fingerprint_hits=counts, domains_unscanned=unscanned,
                        leaking_domains=leaking, ngram_width=width, scan_scope=scope,
                        scan_attributed_to=attributed, fingerprint_file=FINGERPRINTS,
                        reason=None if ok else "eval-leak")


@check(id="manifest_replay_reproduces_the_corpus_and_the_four_integer_counts", weight=4, knockout=False, kind="replay")
def test_manifest_replay_reproduces_the_corpus_and_the_four_integer_counts():
    replay = run_record().get("manifest_replay")
    replay = replay if isinstance(replay, dict) else {}
    if not replay:
        return False, evidence(target="run_record", reason="recipe-corpus-divergence",
                               detail="the verifier recorded no re-execution of the mixture "
                                      "manifest")
    try:
        submitted_digest = load_submission().get("corpus_sha256")
    except Exception:
        submitted_digest = None
    produced = replay.get("corpus_sha256")
    fresh = bool(replay.get("fresh_checkout"))
    replay_counts = integer_map(replay.get("per_domain_tokens"))
    realised = integer_domain_map("per_domain_tokens")
    digest_ok = hex64(produced) and hex64(submitted_digest) and produced == submitted_digest
    counts_ok = bool(replay_counts) and bool(realised) and replay_counts == realised
    ok = fresh and digest_ok and counts_ok
    return ok, evidence(target="run_record", fresh_checkout=fresh,
                        submitted_corpus_sha256=submitted_digest, replayed_corpus_sha256=produced,
                        replayed_per_domain_tokens=replay_counts,
                        realised_per_domain_tokens=realised,
                        reason=None if ok else "recipe-corpus-divergence")


@check(id="mixture_and_dual_wall_accounting_declared", weight=3, knockout=False, kind="process")
def test_mixture_and_dual_wall_accounting_declared():
    declaration = run_record().get("agent_budget_declaration")
    if declaration is None:
        return False, evidence(target="run_record", reason="no-agent-declaration")
    try:
        fields = json.loads(declaration) if isinstance(declaration, str) else dict(declaration)
    except Exception as exc:
        return False, evidence(target="run_record", reason="declaration-unparseable",
                               error=str(exc))
    absent = [key for key in ("build_seconds", "train_seconds", "per_domain_weights",
                              "repetition_epochs", "emission_curriculum") if key not in fields]
    if absent:
        return False, evidence(target="run_record", declared=sorted(fields), missing=absent,
                               reason="declaration-incomplete")
    try:
        manifest_weights = weights()
    except Exception:
        manifest_weights = {}
    declared_weights = fields.get("per_domain_weights")
    agrees = (isinstance(declared_weights, dict) and bool(manifest_weights)
              and set(declared_weights) == set(manifest_weights))
    if agrees:
        for domain in manifest_weights:
            left = as_float(declared_weights.get(domain))
            right = as_float(manifest_weights.get(domain))
            if left is None or right is None or abs(left - right) > 1e-9:
                agrees = False
                break
    block = measured()
    build = as_float(block.get("build_seconds"))
    train = as_float(block.get("train_seconds"))
    build_ok = build is not None and build <= BUILD_WALL_SECONDS
    train_ok = train is not None and train <= TRAIN_WALL_SECONDS
    ok = agrees and build_ok and train_ok
    if not build_ok:
        reason = "build-wallclock-exceeded"
    elif not train_ok:
        reason = "train-wallclock-exceeded"
    elif not agrees:
        reason = "declared-mixture-divergence"
    else:
        reason = None
    return ok, evidence(target="run_record", declared_weights=declared_weights,
                        manifest_weights=manifest_weights, host_build_seconds=build,
                        host_train_seconds=train, build_ceiling=BUILD_WALL_SECONDS,
                        train_ceiling=TRAIN_WALL_SECONDS, reason=reason)


@check(id="mixture_manifest_declares_the_four_disclosed_domains", weight=5, knockout=True, kind="mixture")
def test_mixture_manifest_declares_the_four_disclosed_domains():
    if not os.path.exists(SUBMISSION):
        return False, evidence(target="mixture_manifest", reason="no-submission", path=SUBMISSION)
    try:
        declared = weights()
    except Exception as exc:
        return False, evidence(target="mixture_manifest", error=str(exc),
                               reason="declared-mixture-divergence")
    unknown = sorted(label for label in declared if label not in DOMAINS)
    absent = [domain for domain in DOMAINS if domain not in declared]
    numeric = {}
    for label, value in declared.items():
        number = as_float(value)
        if number is not None:
            numeric[label] = number
    unusable = sorted(set(declared) - set(numeric))
    outside = sorted(label for label, number in numeric.items() if not 0.0 <= number <= 1.0)
    total = sum(numeric.get(domain, 0.0) for domain in DOMAINS)
    ok = not (unknown or absent or unusable or outside) and abs(total - 1.0) <= 1e-9
    return ok, evidence(target="mixture_manifest", declared_labels=sorted(declared),
                        unknown_labels=unknown, missing_domains=absent, non_numeric=unusable,
                        outside_unit_interval=outside, weight_total=total,
                        reason=None if ok else "declared-mixture-divergence")


@check(id="per_domain_weights_are_post_dedup_token_shares", weight=5, knockout=True, kind="mixture")
def test_per_domain_weights_are_post_dedup_token_shares():
    try:
        declared = weights()
        basis = str(mixture_manifest().get("weight_basis", "")).strip().lower()
    except Exception as exc:
        return False, evidence(target="mixture_manifest", error=str(exc),
                               reason="declared-mixture-divergence")
    realised = integer_domain_map("per_domain_tokens")
    if not realised:
        return False, evidence(target="mixture_manifest", reason="realised-counts-unavailable",
                               detail="the verifier recorded no four-domain integer token counts")
    total = sum(realised.values())
    if total <= 0:
        return False, evidence(target="mixture_manifest", reason="declared-mixture-divergence",
                               detail="the emitted corpus carries no tokens to take a share of")
    drift = {}
    for domain in DOMAINS:
        number = as_float(declared.get(domain))
        drift[domain] = (None if number is None
                         else abs(number - realised[domain] / float(total)))
    unusable = sorted(domain for domain in DOMAINS if drift[domain] is None)
    worst_drift = max([drift[d] for d in DOMAINS if drift[d] is not None] or [None])
    # WHICH WRONG BASIS. When the token comparison misses, the same comparison is run against
    # the two bases that produce a plausible-looking vector for free, so the report names the
    # mistake instead of only its size.
    matched_instead = []
    for name in ("per_domain_documents", "per_domain_pre_dedup_tokens"):
        other = integer_domain_map(name)
        other_total = sum(other.values()) if other else 0
        if other_total <= 0:
            continue
        spread = [abs(as_float(declared.get(d)) - other[d] / float(other_total))
                  for d in DOMAINS if as_float(declared.get(d)) is not None]
        if spread and max(spread) <= WEIGHT_TOLERANCE:
            matched_instead.append(name)
    ok = (not unusable) and basis == "post_dedup_tokens" and worst_drift is not None \
        and worst_drift <= WEIGHT_TOLERANCE
    return ok, evidence(target="mixture_manifest", weight_basis=basis, tolerance=WEIGHT_TOLERANCE,
                        worst_absolute_drift=worst_drift, non_numeric_weights=unusable,
                        matched_basis_instead=matched_instead,
                        reason=None if ok else "declared-mixture-divergence")


@check(id="repeated_spans_charged_to_the_budget_each_time", weight=4, knockout=False, kind="repetition")
def test_repeated_spans_charged_to_the_budget_each_time():
    realised = integer_domain_map("per_domain_tokens")
    distinct = integer_domain_map("per_domain_distinct_span_tokens")
    consumed = measured().get("consumed_tokens")
    if not realised or not distinct or not isinstance(consumed, int) or isinstance(consumed, bool):
        return False, evidence(reason="repetition-accounting-unavailable",
                               detail="the verifier recorded no integer consumed count with the "
                                      "four realised and four distinct-span token counts")
    total = sum(realised.values())
    charged = total == consumed
    epochs = repetition_epochs()
    unpaid = [domain for domain in DOMAINS
              if epochs.get(domain, 1.0) > 1.0 and realised[domain] <= distinct[domain]]
    ok = charged and not unpaid
    reason = None
    if not charged:
        reason = "token-budget-accounting-divergence"
    elif unpaid:
        reason = "repetition-not-charged"
    return ok, evidence(per_domain_tokens=realised, per_domain_distinct_span_tokens=distinct,
                        consumed_tokens=consumed, declared_epochs=epochs,
                        domains_repeating_without_paying=unpaid, reason=reason)


@check(id="selection_policy_rests_on_its_own_measurement", weight=4, knockout=False, kind="measurement")
def test_selection_policy_rests_on_its_own_measurement():
    block = run_record().get("selection_evidence")
    if not isinstance(block, dict):
        return False, evidence(target="run_record", reason="prior-asserted-over-measurement",
                               detail="the run recorded no selection evidence at all, so the "
                                      "weights rest on nothing this environment produced")
    own = block.get("own_measurements")
    own = own if isinstance(own, list) else []
    covered = {}
    for entry in own:
        if not isinstance(entry, dict):
            continue
        domain = entry.get("domain")
        try:
            scored = int(entry.get("tokens_scored", 0))
        except Exception:
            scored = 0
        estimator = str(entry.get("estimator", "")).strip()
        artifact = str(entry.get("recorded_at", "")).strip()
        if domain in DOMAINS and scored > 0 and estimator and artifact:
            covered[domain] = scored
    unmeasured = [domain for domain in DOMAINS if domain not in covered]
    cited = [str(source).strip().lower()
             for source in (block.get("cited_sources") or []) if str(source).strip()]
    decoy_only = bool(cited) and all(
        any(token in source for token in DECOY_TOKENS) for source in cited)
    ok = not unmeasured and not decoy_only
    return ok, evidence(target="run_record", domains_measured_here=sorted(covered),
                        domains_unmeasured=unmeasured, cited_sources=cited,
                        cites_only_shipped_carriers=decoy_only,
                        reason=None if ok else "prior-asserted-over-measurement")


@check(id="span_domain_read_from_the_source_manifest", weight=5, knockout=True, kind="attribution")
def test_span_domain_read_from_the_source_manifest():
    try:
        table = spans()
    except Exception as exc:
        return False, evidence(target="source_manifest", error=str(exc), reason="no-submission")
    manifest = source_manifest()
    recorded = measured().get("span_domain_resolution") or {}
    if not isinstance(recorded, dict):
        recorded = {}
    if not manifest and not recorded:
        return False, evidence(target="source_manifest", reason="source-manifest-unavailable",
                               detail="neither the shipped source manifest nor the verifier's own "
                                      "resolution is present; unproven attribution is not proven "
                                      "attribution")
    malformed, unresolved, relabelled = [], [], []
    for position, record in enumerate(table):
        if not record:
            malformed.append(position)
            continue
        for triple in record:
            source_id, offset, length, asserted = span_fields(triple)
            if source_id is None or offset < 0 or length <= 0:
                malformed.append(position)
                continue
            actual = resolved_domain(source_id, manifest, recorded)
            if actual is None:
                unresolved.append(source_id)
            elif asserted is not None and asserted != actual:
                relabelled.append(source_id)
    if malformed or unresolved:
        reason = "foreign-content"
    elif relabelled:
        reason = "declared-mixture-divergence"
    else:
        reason = None
    return reason is None, evidence(target="source_manifest", records=len(table),
                                    malformed_records=sorted(set(malformed))[:8],
                                    unresolved_source_ids=sorted(set(unresolved))[:8],
                                    relabelled_source_ids=sorted(set(relabelled))[:8],
                                    reason=reason)


@check(id="token_budget_counted_under_the_frozen_tokenizer", weight=5, knockout=True, kind="budget")
def test_token_budget_counted_under_the_frozen_tokenizer():
    block = measured()
    counted = block.get("consumed_tokens")
    if not isinstance(counted, int) or isinstance(counted, bool):
        return False, evidence(reason="token-budget-unmeasured",
                               detail="the verifier recorded no integer count of its own encode of "
                                      "the emitted corpus")
    try:
        submitted = load_submission().get("consumed_tokens")
    except Exception:
        submitted = None
    digests = block.get("frozen_tokenizer_sha256")
    digests = digests if isinstance(digests, dict) else {}
    before, after = digests.get("before"), digests.get("after")
    tokenizer_held = hex64(before) and before == after
    within = counted <= TOKEN_BUDGET
    agrees = isinstance(submitted, int) and not isinstance(submitted, bool) and submitted == counted
    ok = within and agrees and tokenizer_held
    if not within:
        reason = "token-budget-exceeded"
    elif not tokenizer_held:
        reason = "frozen-trainer-modified"
    elif not agrees:
        reason = "declared-token-count-divergence"
    else:
        reason = None
    return ok, evidence(verifier_counted_tokens=counted, submitted_consumed_tokens=submitted,
                        budget=TOKEN_BUDGET, tokenizer_sha256_before=before,
                        tokenizer_sha256_after=after, tokenizer_path=FROZEN_TOKENIZER,
                        reason=reason)


@check(id="worst_domain_bits_per_byte_ramp", weight=10, knockout=True, kind="outcome")
def test_worst_domain_bits_per_byte_ramp():
    c = require_measured("floor", "knee", "dichotomizing_threshold")
    # require_measured runs FIRST, before the submission, the manifest or the record is touched.
    # Reading a delivered byte ahead of it lets a missing-artifact failure be caught before the
    # unmeasured signal fires; the verifier then reports gradeable true with r_det 0.0, which
    # asserts the agent scored zero when the true claim is that the slot is not yet measurable.
    worst, worst_domain = measure()
    # Bits per byte DESCENDS, so the ramp is read in the descending direction: the floor is the
    # LARGER value and the knee the smaller. Subtracting in the ascending order would score a
    # well-mixed corpus at zero and an uncurated one at full reward.
    span = c["floor"] - c["knee"]
    s = 0.0 if span <= 0 else max(0.0, min(1.0, (c["floor"] - worst) / span))
    return s >= c["dichotomizing_threshold"], evidence(worst_domain_bits_per_byte=worst,
                                                       worst_domain=worst_domain, s_outcome=s)


# ------------------------------------------------------------------------------------------
# Reading the delivered bytes. One submission, one shipped source manifest, one harness record.
# Absent is REPORTED by every reader here, never guessed at and never allowed to look like a
# pass: on this slot an unproven attribution and a correct attribution are the same bytes.
# ------------------------------------------------------------------------------------------

def load_submission():
    """The graded artifact: the emitted order, the mixture that produced it, and its spans."""
    with open(SUBMISSION) as handle:
        doc = json.load(handle)
    if not isinstance(doc, dict):
        raise ValueError("the deliverable must be a JSON object carrying a mixture manifest")
    return doc


def describe(obj):
    return "keys=" + ",".join(sorted(obj)[:8])


def mixture_manifest():
    man = load_submission().get("mixture_manifest")
    if not isinstance(man, dict):
        raise ValueError("mixture_manifest is not an object")
    return man


def weights():
    """The declared per-domain sampling weights, as the submission wrote them."""
    w = mixture_manifest().get("weights")
    if not isinstance(w, dict) or not w:
        raise ValueError("mixture_manifest.weights is not a non-empty mapping")
    return dict((str(k), v) for k, v in w.items())


def repetition_epochs():
    """domain -> declared epoch count; 1 for anything the manifest does not name."""
    try:
        declared = mixture_manifest().get("repetition_epochs")
    except Exception:
        return {}
    if not isinstance(declared, dict):
        return {}
    out = {}
    for domain in DOMAINS:
        try:
            out[domain] = float(declared.get(domain, 1))
        except Exception:
            out[domain] = 1.0
    return out


def spans():
    """Per record, the list of (source_id, offset, length) triples it was assembled from.

    Recombination is permitted -- short scientific and mathematical fragments are meant to be
    packed into full-length records -- so a record carries a LIST of triples, not one triple.
    """
    table = load_submission().get("spans")
    if not isinstance(table, list) or not table:
        raise ValueError("spans is not a non-empty list")
    out = []
    for entry in table:
        out.append(entry if isinstance(entry, list) else [entry])
    return out


def span_fields(triple):
    """(source_id, offset, length, asserted_domain) from either shape a record may use."""
    if isinstance(triple, dict):
        source = triple.get("source_id")
        offset = triple.get("offset")
        length = triple.get("length")
        asserted = triple.get("domain")
    elif isinstance(triple, (list, tuple)) and len(triple) >= 3:
        source, offset, length = triple[0], triple[1], triple[2]
        asserted = triple[3] if len(triple) > 3 else None
    else:
        return None, None, None, None
    try:
        offset = int(offset)
        length = int(length)
    except Exception:
        return None, None, None, None
    if not isinstance(source, str) or not source:
        return None, None, None, None
    return source, offset, length, (str(asserted) if asserted is not None else None)


def source_manifest():
    """source_id -> domain, from the shipped four-corpus manifest.

    Empty when the corpus has not landed in this tree. Empty is not a pass anywhere: the checks
    that need attribution fall back to the verifier's own recorded resolution and fail closed
    when neither is present.
    """
    if not os.path.exists(SOURCE_MANIFEST):
        return {}
    try:
        with open(SOURCE_MANIFEST) as handle:
            doc = json.load(handle)
    except Exception:
        return {}
    if not isinstance(doc, dict):
        return {}
    doc = doc.get("sources", doc)
    out = {}
    for source_id, entry in doc.items() if isinstance(doc, dict) else []:
        domain = entry.get("domain") if isinstance(entry, dict) else entry
        if isinstance(domain, str):
            out[str(source_id)] = domain
    return out


def run_record():
    """What the graded run and the verifier recorded about the run.

    The agent writes part of this file, so it can be absent, truncated, or not JSON at all.
    Every one of those is an empty record here: an unparseable declaration declares nothing, and
    each check then reports its own missing-declaration reason instead of taking the verifier
    down with a decode error and returning no report about anything.
    """
    if not os.path.exists(RUN_RECORD):
        return {}
    try:
        with open(RUN_RECORD) as handle:
            doc = json.load(handle)
    except Exception:
        return {}
    return doc if isinstance(doc, dict) else {}


def measured():
    """The verifier's own measurements over the emitted corpus. Never an agent-reported number."""
    block = run_record().get("verifier_measured")
    return block if isinstance(block, dict) else {}


def integer_domain_map(name):
    """The four per-domain counts under `name`, as EXACT integers, or {} if that is not what they

    are. Integers are the point: per-domain weight realisation is exact token accounting, so a
    count arriving as 2.5e8 is a float proportion target wearing a count's name and the replay
    comparison it feeds could only ever have been approximate.
    """
    block = measured().get(name)
    if not isinstance(block, dict):
        return {}
    out = {}
    for domain in DOMAINS:
        value = block.get(domain)
        if isinstance(value, bool) or not isinstance(value, int):
            return {}
        out[domain] = value
    return out


def integer_map(block):
    """The same strictness applied to a mapping already in hand (the replay's own counts)."""
    if not isinstance(block, dict):
        return {}
    out = {}
    for domain in DOMAINS:
        value = block.get(domain)
        if isinstance(value, bool) or not isinstance(value, int):
            return {}
        out[domain] = value
    return out


def resolved_domain(source_id, manifest, recorded):
    return manifest.get(source_id, recorded.get(source_id))


def emitted_domain_order():
    """The domain of each emitted record, in emission order; [] when it cannot be resolved.

    A record recombines fragments; its domain is the domain of its spans. A record whose spans
    disagree is reported as 'mixed', which is a real answer rather than a failure to read: the
    interleave check cares whether every block puts all four domains in front of the trainer.
    """
    manifest = source_manifest()
    recorded = measured().get("span_domain_resolution") or {}
    if not isinstance(recorded, dict):
        recorded = {}
    if not manifest and not recorded:
        return []
    try:
        table = spans()
    except Exception:
        return []
    order = []
    for record in table:
        found = set()
        for triple in record:
            source_id = span_fields(triple)[0]
            if source_id is None:
                continue
            domain = resolved_domain(source_id, manifest, recorded)
            if domain is not None:
                found.add(domain)
        if len(found) == 1:
            order.append(found.pop())
        elif found:
            order.append("mixed")
        else:
            order.append(None)
    return order


def hex64(value):
    return (isinstance(value, str) and len(value) == 64
            and all(c in "0123456789abcdef" for c in value))


def as_float(value):
    try:
        number = float(value)
    except Exception:
        return None
    if number != number or number in (float("inf"), float("-inf")):
        return None
    return number


def measure():
    """(b_worst, argmax domain): the WORST of the four per-domain bits-per-byte values.

    All four are required. Reducing whichever domains happen to have been reported would let a
    three-domain report become a graded value, and the max-min structure is exactly the claim
    that three domains are not the score. The reduction runs in the fixed DOMAINS order so the
    argmax is stable in identity as well as in value.
    """
    block = measured().get("per_domain_bits_per_byte")
    if not isinstance(block, dict):
        raise ConstantUnmeasured(
            "the frozen evaluator reported no per-domain bits per byte; b_worst is a max over "
            "four and is undefined while any of them is missing")
    values = []
    for domain in DOMAINS:
        number = as_float(block.get(domain))
        if number is None:
            raise ConstantUnmeasured(
                "the frozen evaluator reported no finite bits per byte for the %s domain; "
                "b_worst is a max over four and is undefined while any of them is missing"
                % domain)
        values.append((domain, number))
    worst_domain, worst = values[0]
    for domain, number in values[1:]:
        if number > worst:
            worst_domain, worst = domain, number
    return worst, worst_domain
